package dev.pocketengine.runtime.usage;
import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public final class RealtimeUsageTest {
 @Test public void actualRealtimeTokenAndMediaPathsRemainDistinctWithoutDoubleAdding()throws Exception{ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_realtime");usage.observe(new JSONObject().put("model","actual-realtime").put("usage",new JSONObject().put("input_tokens",31).put("output_tokens",17).put("total_tokens",48).put("input_token_details",new JSONObject().put("cached_tokens",8).put("text_tokens",7).put("audio_tokens",24)).put("output_token_details",new JSONObject().put("text_tokens",4).put("audio_tokens",13))),ProviderUsage.Stage.FINAL);JSONObject actual=usage.toJson();assertEquals(31,actual.getJSONObject("counters").getJSONObject("INPUT").getLong("value"));assertEquals(17,actual.getJSONObject("counters").getJSONObject("OUTPUT").getLong("value"));assertEquals(8,actual.getJSONObject("counters").getJSONObject("CACHE_READ").getLong("value"));assertEquals(24,actual.getJSONObject("mediaCounters").getJSONObject("INPUT_AUDIO").getLong("value"));assertEquals("usage.input_token_details.audio_tokens",actual.getJSONObject("mediaCounters").getJSONObject("INPUT_AUDIO").getString("sourcePath"));assertTrue(actual.isNull("outputIncludesReasoning"));assertTrue(actual.isNull("actualCost"));}
 @Test public void missingCountsAndAbsentMediaAreUnknownRatherThanFreeZero()throws Exception{ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_realtime");usage.observe(new JSONObject().put("usage",new JSONObject().put("input_tokens",0)),ProviderUsage.Stage.FINAL);JSONObject result=usage.toJson();assertEquals(0,result.getJSONObject("counters").getJSONObject("INPUT").getLong("value"));assertTrue(result.getJSONObject("counters").getJSONObject("OUTPUT").isNull("value"));assertEquals("unknown",result.getJSONObject("mediaCounters").getJSONObject("OUTPUT_AUDIO").getString("source"));assertTrue(result.isNull("subscriptionRemaining"));}
 @Test public void malformedMediaDoesNotEraseActualTotalOrBorrowTextAsAudio()throws Exception{ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_realtime");usage.observe(new JSONObject().put("usage",new JSONObject().put("input_tokens",20).put("input_token_details",new JSONObject().put("audio_tokens",-1).put("text_tokens",20))),ProviderUsage.Stage.PARTIAL);JSONObject result=usage.toJson();assertEquals(20,result.getJSONObject("counters").getJSONObject("INPUT").getLong("value"));assertEquals("unknown",result.getJSONObject("mediaCounters").getJSONObject("INPUT_AUDIO").getString("source"));assertEquals(20,result.getJSONObject("mediaCounters").getJSONObject("INPUT_TEXT").getLong("value"));assertTrue(result.getJSONArray("invalidFields").toString().contains("usage.input_token_details.audio_tokens"));}
 @Test public void asrTokenUsageIsASeparateProtocolAndDoesNotPretendSpeechReplyTotals()throws Exception{ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_realtime_transcription");usage.observe(new JSONObject().put("usage",new JSONObject().put("type","tokens").put("input_tokens",13).put("output_tokens",9).put("total_tokens",22).put("input_token_details",new JSONObject().put("text_tokens",0).put("audio_tokens",13))),ProviderUsage.Stage.FINAL);JSONObject result=usage.toJson();assertEquals("openai_realtime_transcription",result.getString("protocol"));assertEquals(22,result.getJSONObject("counters").getJSONObject("TOTAL").getLong("value"));assertEquals(13,result.getJSONObject("mediaCounters").getJSONObject("INPUT_AUDIO").getLong("value"));assertTrue(result.getJSONObject("mediaCounters").getJSONObject("OUTPUT_AUDIO").isNull("value"));assertTrue(result.isNull("actualCost"));assertTrue(result.isNull("outputIncludesReasoning"));}
 @Test public void asrDurationKeepsItsActualUnitAndAllAbsentTokensUnknown()throws Exception{ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_realtime_transcription");usage.observe(new JSONObject().put("usage",new JSONObject().put("type","duration").put("seconds",new java.math.BigDecimal("12.75"))),ProviderUsage.Stage.FINAL);JSONObject result=usage.toJson(),measure=result.getJSONObject("providerMeasures").getJSONObject("AUDIO_SECONDS");assertEquals("12.75",measure.get("value").toString());assertEquals("seconds",measure.getString("unit"));assertTrue(measure.getBoolean("notConvertedToTokensOrMoney"));assertEquals("usage.seconds",measure.getString("sourcePath"));for(String key:new String[]{"INPUT","OUTPUT","TOTAL"})assertTrue(result.getJSONObject("counters").getJSONObject(key).isNull("value"));assertTrue(result.isNull("actualCost"));}
 @Test public void unknownAsrShapeAndHugeDurationNeverBecomeGuessedTokensOrUnboundedDecimalText()throws Exception{ProviderUsage.Collector usage=new ProviderUsage.Collector("openai_realtime_transcription");usage.observe(new JSONObject().put("usage",new JSONObject().put("input_tokens",99)),ProviderUsage.Stage.FINAL);assertTrue(usage.toJson().getJSONObject("counters").getJSONObject("INPUT").isNull("value"));usage.observe(new JSONObject().put("usage",new JSONObject().put("type","duration").put("seconds",new java.math.BigDecimal("1E+100000000"))),ProviderUsage.Stage.FINAL);JSONObject result=usage.toJson();assertFalse(result.getJSONObject("providerMeasures").has("AUDIO_SECONDS"));assertTrue(result.getJSONArray("invalidFields").toString().contains("usage.seconds"));assertTrue(result.getJSONObject("counters").getJSONObject("TOTAL").isNull("value"));}
}
